import os
import torch


class Config:
    """
    Configuration class for the 2.5D EfficientNet-FPN segmentation pipeline.
    """

    # ==============================
    # General Settings
    # ==============================
    SEED = 42
    DEBUG = False  # Set to True to run on a small subset for debugging
    DEBUG_SAMPLE_SIZE = 100  # Number of samples to use in debug mode

    # ==============================
    # Directories and Paths
    # ==============================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the metadata script
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Working directory for artifacts (checkpoints, cache)
    WORKING_DIR = "./working/idea_7"
    os.makedirs(WORKING_DIR, exist_ok=True)

    # Model checkpoint path
    MODEL_PATH = os.path.join(WORKING_DIR, "best_model.pth")

    # Submission output path
    SUBMISSION_DIR = "./submission"
    os.makedirs(SUBMISSION_DIR, exist_ok=True)
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==============================
    # Data Configuration
    # ==============================
    IMG_SIZE = 256  # Input resolution (256x256)
    IN_CHANNELS = 3  # 2.5D Input: Slice i-1, Slice i, Slice i+1
    NUM_CLASSES = 3  # Large Bowel, Small Bowel, Stomach
    CLASSES = ["large_bowel", "small_bowel", "stomach"]

    # Normalization parameters (Min-Max per volume is used, but these can be placeholders)
    # 2.5D normalization is handled in the dataset class

    # ==============================
    # Model Configuration
    # ==============================
    MODEL_NAME = "efficientnet_b0"
    ENCODER_WEIGHTS = "imagenet"
    DECODER_CHANNELS = [256, 128, 64, 32, 16]  # FPN specific channels if needed

    # ==============================
    # Training Hyperparameters
    # ==============================
    BATCH_SIZE = 32
    EPOCHS = 15
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-2  # For AdamW

    # Scheduler settings (Cosine Annealing)
    T_MAX = EPOCHS  # Cycle length
    ETA_MIN = 1e-6  # Minimum learning rate

    # ==============================
    # Compute
    # ==============================
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4  # Number of dataloader workers (12 vCPUs available)

    # ==============================
    # Inference / Post-processing
    # ==============================
    THRESHOLD = 0.5  # Probability threshold for binarization
    USE_3D_CONN_COMP = True  # Enable 3D connected component analysis
